/* ===================== APP GIỌNG: bán tự động bằng kho mã (sheet "GIỌNG – Mã truy cập") ===================== */
/* Lấy mã "Chưa cấp" từ dưới lên (số 49, 48...), để anh vẫn cấp tay từ trên xuống mà không trùng. */
const GIONG_SHEET_ID = '1gRvtw8rKboQltMMb1XXa5hTNzQYnMSsD4xR9LxTm1oE';
function giongSheet_() { return SpreadsheetApp.openById(GIONG_SHEET_ID).getSheets()[0]; }
function giongTake_(name, email, phone, orderCode, note) {
  const sh = giongSheet_(), v = sh.getDataRange().getValues();
  for (let i = v.length - 1; i >= 1; i--) {
    if (String(v[i][5]).trim() === 'Chưa cấp' && /^GIONG-/.test(String(v[i][1]))) {
      sh.getRange(i + 1, 3, 1, 5).setValues([[name + ' (' + email + ')', phone ? "'" + phone : '', Utilities.formatDate(new Date(), 'Asia/Ho_Chi_Minh', 'dd/MM/yyyy'), 'Đã cấp (tự động)', note + ' ' + orderCode]]);
      let left = 0; v.forEach((r, k) => { if (k >= 1 && k !== i && String(r[5]).trim() === 'Chưa cấp') left++; });
      if (left < 5) giongLowAlert_(left);
      return String(v[i][1]);
    }
  }
  giongLowAlert_(0);
  return '';
}
function giongLowAlert_(left) {
  const props = PropertiesService.getScriptProperties(), today = Utilities.formatDate(new Date(), 'Asia/Ho_Chi_Minh', 'yyyy-MM-dd');
  if (props.getProperty('GIONG_ALERT') === today) return;
  props.setProperty('GIONG_ALERT', today);
  MailApp.sendEmail(ADMINS[0], '[GIỌNG] Kho mã còn ' + left + ' mã', 'Kho mã app GIỌNG chỉ còn ' + left + ' mã "Chưa cấp". Anh nhắn Claude tạo thêm mã (thêm vào biến ACCESS_CODES trên Vercel và vào sheet GIỌNG – Mã truy cập).');
  log_('GIỌNG sắp hết mã', 'còn ' + left);
}
function giongMail_(email, name, acc, gift) {
  const inner = '<p>Chào ' + esc_(name) + ',</p><p>' + (gift ? 'Quà tặng kèm khoá <b>LÀM VIDEO KHÔNG CẦN LÊN HÌNH</b>: mã dùng app GIỌNG của bạn.' : 'Đã nhận thanh toán. Cảm ơn bạn đã mua app GIỌNG.') + '</p>' +
    '<table style="border-collapse:collapse;width:100%;font-size:15px">' + row_('Trang app', '<a href="https://giong.lequydai.com">giong.lequydai.com</a>') +
    row_('Mã truy cập', '<b style="font-size:20px;letter-spacing:1px">' + acc + '</b>') + '</table>' +
    '<p><b>Cách dùng:</b> mở giong.lequydai.com, dán mã vào ô "Mã truy cập", bấm Vào app. Mỗi máy nhập mã một lần, dùng được trên điện thoại và máy tính. App dùng key Gemini của bạn, trong app có hướng dẫn lấy key miễn phí.</p>' +
    '<p style="text-align:center;margin:22px 0"><a href="https://giong.lequydai.com" style="background:#FED227;color:#041431;font-weight:900;padding:14px 28px;border-radius:10px;text-decoration:none;display:inline-block">MỞ APP GIỌNG</a></p>' +
    '<p style="color:#5d6785;font-size:13px">Giữ mã này cho riêng bạn, không chia sẻ.</p>';
  MailApp.sendEmail({ to: email, subject: '[APP GIỌNG] Mã truy cập của bạn', htmlBody: mailWrap_('Mã dùng app GIỌNG', inner, 'giong'), name: CFG.BRAND });
}
function giongDeliver_(sh, i, row) {
  const [, code, name, email, phone] = row;
  if (String(row[11] || '').indexOf('GIONG-') === 0) { sh.getRange(i + 1, 7).setValue(ST.DONE); return; }
  if (String(row[9] || '').indexOf('HẾT MÃ') >= 0) return;
  const acc = giongTake_(String(name), String(email).toLowerCase(), String(phone || '').replace(/^'/, ''), code, 'Mua web');
  if (!acc) { sh.getRange(i + 1, 10).setValue('HẾT MÃ – chờ anh cấp tay'); log_('GIỌNG hết mã', code); return; }
  sh.getRange(i + 1, 12).setValue(acc);
  try { giongMail_(String(email), name, acc, false); } catch (e) { log_('lỗi mail GIỌNG', code + ' ' + e); }
  sh.getRange(i + 1, 7).setValue(ST.DONE); sh.getRange(i + 1, 9).setValue(new Date());
  log_('giao mã GIỌNG', code + ' · ' + email);
}
/* Khoá LÀM VIDEO KHÔNG CẦN LÊN HÌNH tặng kèm app GIỌNG */
function giongGift_(sh, i, row) {
  try {
    const [, code, name, email, phone] = row;
    const acc = giongTake_(String(name), String(email).toLowerCase(), String(phone || '').replace(/^'/, ''), code, 'Tặng kèm khoá');
    if (!acc) { log_('GIỌNG hết mã (quà khoá)', code); return; }
    sh.getRange(i + 1, 12).setValue(acc);
    giongMail_(String(email), name, acc, true);
    log_('tặng mã GIỌNG', code + ' · ' + email);
  } catch (e) { log_('lỗi tặng GIỌNG', String(e)); }
}
function giongStatus_(code) {
  code = String(code || '').toUpperCase();
  const rows = sheet_(SH.ORDERS).getDataRange().getValues();
  for (let i = 1; i < rows.length; i++) if (String(rows[i][1]) === code && rows[i][10] === 'giong') {
    const paid = rows[i][6] === ST.PAID || rows[i][6] === ST.DONE;
    const acc = String(rows[i][11] || '');
    return { ok: true, paid: paid, ready: !!acc, access: acc || '' };
  }
  return { ok: false, msg: 'Không tìm thấy đơn' };
}
/* Chạy thử 1 lần trong trình soạn thảo: kiểm tra máy chủ đọc được sheet mã GIỌNG (không cấp mã nào) */
function thuKhoGiong() {
  const v = giongSheet_().getDataRange().getValues();
  const left = v.filter((r, k) => k >= 1 && String(r[5]).trim() === 'Chưa cấp').length;
  log_('kiểm tra kho GIỌNG', 'đọc được, còn ' + left + ' mã chưa cấp');
  return left;
}
